CREATE TABLE partner_delivery_sites (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
 company_id UUID NOT NULL REFERENCES "Company"(id),
 project_id UUID REFERENCES projects(id),
 operational_label TEXT NOT NULL CHECK (btrim(operational_label)<>''),
 delivery_alias TEXT NOT NULL UNIQUE,
 location_details JSONB NOT NULL DEFAULT '{}'::jsonb,
 receiving_contact JSONB NOT NULL DEFAULT '{}'::jsonb,
 status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK (status IN ('ACTIVE','INACTIVE')),
 created_by UUID NOT NULL REFERENCES "User"(id),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TYPE "SupplierDeliveryTrancheStatus" AS ENUM ('PLANNED','SUPPLIER_CONFIRMED','DATE_CHANGED','READY_FOR_DELIVERY');
CREATE TABLE supplier_po_delivery_tranches (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
 supplier_purchase_order_line_id UUID NOT NULL REFERENCES supplier_purchase_order_lines(id),
 supplier_po_release_line_allocation_id UUID NOT NULL REFERENCES supplier_po_release_line_allocations(id),
 partner_delivery_site_id UUID NOT NULL REFERENCES partner_delivery_sites(id),
 supplier_po_line_confirmation_event_id UUID NOT NULL REFERENCES supplier_po_line_confirmation_events(id),
 quantity NUMERIC(18,4) NOT NULL CHECK(quantity>0),
 status "SupplierDeliveryTrancheStatus" NOT NULL DEFAULT 'PLANNED',
 created_by UUID NOT NULL REFERENCES "User"(id),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE supplier_po_delivery_tranche_change_events (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
 tranche_id UUID NOT NULL REFERENCES supplier_po_delivery_tranches(id),
 previous_date DATE NOT NULL,
 new_date DATE NOT NULL,
 reason TEXT NOT NULL CHECK(btrim(reason)<>''),
 actor_user_id UUID NOT NULL REFERENCES "User"(id),
 created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 correlation_id UUID
);
CREATE INDEX delivery_tranches_allocation_idx ON supplier_po_delivery_tranches(supplier_po_release_line_allocation_id);
CREATE INDEX delivery_tranches_line_idx ON supplier_po_delivery_tranches(supplier_purchase_order_line_id);
CREATE INDEX delivery_tranche_changes_idx ON supplier_po_delivery_tranche_change_events(tranche_id,created_at);
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['partner_delivery_sites','supplier_po_delivery_tranches','supplier_po_delivery_tranche_change_events'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON TABLE public.%I FROM sco_runtime,sco_internal_executor',t); END LOOP; END $$;
INSERT INTO "Permission"(id,code,description) VALUES
(gen_random_uuid(),'supplier_po.delivery_schedule.read_all','Read all SCO delivery schedules'),
(gen_random_uuid(),'supplier_po.delivery_schedule.read_assigned','Read assigned SCO delivery schedules'),
(gen_random_uuid(),'supplier_po.delivery_schedule.manage','Manage SCO delivery schedules') ON CONFLICT(code) DO NOTHING;
CREATE OR REPLACE FUNCTION public.delivery_scope_allowed(p_actor uuid,p_line uuid) RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT public.internal_has_capability(p_actor,'supplier_po.delivery_schedule.read_all') OR EXISTS(SELECT 1 FROM supplier_purchase_order_lines l JOIN supplier_purchase_orders p ON p.id=l.supplier_purchase_order_id JOIN product_identities pi ON pi.id=l.product_identity_id JOIN procurement_engineer_scope_assignments s ON s.actor_user_id=p_actor AND s.purchase_source_id=p.purchase_source_id AND s.product_category_id=pi.category_id AND s.status='ACTIVE' WHERE l.id=p_line) OR EXISTS(SELECT 1 FROM supplier_po_line_responsibilities r WHERE r.supplier_purchase_order_line_id=p_line AND r.actor_user_id=p_actor); $$;
CREATE OR REPLACE FUNCTION public.internal_partner_delivery_site_create(p_actor uuid,p_company uuid,p_project uuid,p_label text,p_location jsonb,p_contact jsonb,p_correlation text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v uuid:=gen_random_uuid(); a text; BEGIN IF NOT public.internal_has_capability(p_actor,'supplier_po.delivery_schedule.manage') THEN RAISE EXCEPTION 'DELIVERY_SCHEDULE_MANAGE_FORBIDDEN'; END IF; IF NOT EXISTS(SELECT 1 FROM "Company" WHERE id=p_company AND type='PARTNER') OR (p_project IS NOT NULL AND NOT EXISTS(SELECT 1 FROM projects WHERE id=p_project AND company_id=p_company)) THEN RAISE EXCEPTION 'DELIVERY_SITE_INVALID'; END IF; a:='SCO-DST-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)); INSERT INTO partner_delivery_sites(id,company_id,project_id,operational_label,delivery_alias,location_details,receiving_contact,created_by) VALUES(v,p_company,p_project,btrim(p_label),a,COALESCE(p_location,'{}'),COALESCE(p_contact,'{}'),p_actor); INSERT INTO audit_logs(actor_user_id,scope,action,entity_type,entity_id,metadata,correlation_id) VALUES(p_actor,'SCO_INTERNAL','partner_delivery_site.created','PartnerDeliverySite',v,jsonb_build_object('companyId',p_company,'alias',a),NULLIF(p_correlation,'')::uuid); RETURN v; END $$;
CREATE OR REPLACE FUNCTION public.internal_supplier_po_delivery_tranche_create(p_actor uuid,p_allocation uuid,p_site uuid,p_confirmation_event uuid,p_quantity numeric,p_correlation text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v uuid:=gen_random_uuid(); l uuid; ev_qty numeric; used numeric; site_company uuid; partner_company uuid; BEGIN IF NOT public.internal_has_capability(p_actor,'supplier_po.delivery_schedule.manage') THEN RAISE EXCEPTION 'DELIVERY_SCHEDULE_MANAGE_FORBIDDEN'; END IF; SELECT a.supplier_purchase_order_line_id,r.partner_company_id INTO l,partner_company FROM supplier_po_release_line_allocations a JOIN procurement_release_lines rl ON rl.id=a.procurement_release_line_id JOIN procurement_releases r ON r.id=rl.release_id WHERE a.id=p_allocation; IF l IS NULL OR NOT public.delivery_scope_allowed(p_actor,l) THEN RAISE EXCEPTION 'DELIVERY_SCHEDULE_SCOPE_REQUIRED'; END IF; SELECT company_id INTO site_company FROM partner_delivery_sites WHERE id=p_site; IF site_company IS NULL OR site_company<>partner_company THEN RAISE EXCEPTION 'DELIVERY_SITE_TENANT_MISMATCH'; END IF; IF NOT EXISTS(SELECT 1 FROM supplier_po_line_confirmation_events e WHERE e.id=p_confirmation_event AND e.supplier_purchase_order_line_id=l) THEN RAISE EXCEPTION 'DELIVERY_CONFIRMATION_EVENT_INVALID'; END IF; SELECT confirmed_quantity_delta INTO ev_qty FROM supplier_po_line_confirmation_events WHERE id=p_confirmation_event; SELECT COALESCE(sum(quantity),0) INTO used FROM supplier_po_delivery_tranches WHERE supplier_po_release_line_allocation_id=p_allocation AND supplier_po_line_confirmation_event_id=p_confirmation_event; IF p_quantity IS NULL OR p_quantity<=0 OR used+p_quantity>LEAST((SELECT allocated_quantity FROM supplier_po_release_line_allocations WHERE id=p_allocation),ev_qty) THEN RAISE EXCEPTION 'DELIVERY_TRANCHE_QUANTITY_EXCEEDED'; END IF; INSERT INTO supplier_po_delivery_tranches(id,supplier_purchase_order_line_id,supplier_po_release_line_allocation_id,partner_delivery_site_id,supplier_po_line_confirmation_event_id,quantity,created_by) VALUES(v,l,p_allocation,p_site,p_confirmation_event,p_quantity,p_actor); INSERT INTO audit_logs(actor_user_id,scope,action,entity_type,entity_id,metadata,correlation_id) VALUES(p_actor,'SCO_INTERNAL','supplier_po.delivery_tranche.created','SupplierDeliveryTranche',v,jsonb_build_object('allocationId',p_allocation,'quantity',p_quantity),NULLIF(p_correlation,'')::uuid); RETURN v; END $$;
CREATE OR REPLACE FUNCTION public.internal_supplier_po_delivery_tranche_date_change(p_actor uuid,p_tranche uuid,p_previous date,p_new date,p_reason text,p_correlation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT public.internal_has_capability(p_actor,'supplier_po.delivery_schedule.manage') THEN RAISE EXCEPTION 'DELIVERY_SCHEDULE_MANAGE_FORBIDDEN'; END IF; IF NOT EXISTS(SELECT 1 FROM supplier_po_delivery_tranches t WHERE t.id=p_tranche AND public.delivery_scope_allowed(p_actor,t.supplier_purchase_order_line_id)) THEN RAISE EXCEPTION 'DELIVERY_SCHEDULE_SCOPE_REQUIRED'; END IF; IF p_previous IS NULL OR p_new IS NULL OR btrim(COALESCE(p_reason,''))='' THEN RAISE EXCEPTION 'DELIVERY_DATE_CHANGE_INVALID'; END IF; INSERT INTO supplier_po_delivery_tranche_change_events(tranche_id,previous_date,new_date,reason,actor_user_id,correlation_id) VALUES(p_tranche,p_previous,p_new,btrim(p_reason),p_actor,NULLIF(p_correlation,'')::uuid); UPDATE supplier_po_delivery_tranches SET status='DATE_CHANGED',updated_at=now() WHERE id=p_tranche; INSERT INTO audit_logs(actor_user_id,scope,action,entity_type,entity_id,metadata,correlation_id) VALUES(p_actor,'SCO_INTERNAL','supplier_po.delivery_tranche.date_changed','SupplierDeliveryTranche',p_tranche,jsonb_build_object('previousDate',p_previous,'newDate',p_new,'reason',p_reason),NULLIF(p_correlation,'')::uuid); END $$;
CREATE OR REPLACE FUNCTION public.internal_supplier_po_delivery_tranche_get(p_actor uuid,p_tranche uuid) RETURNS TABLE(id uuid,supplier_purchase_order_line_id uuid,allocation_id uuid,site_id uuid,quantity numeric,status "SupplierDeliveryTrancheStatus",original_promised_date date,current_promised_date date) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT t.id,t.supplier_purchase_order_line_id,t.supplier_po_release_line_allocation_id,t.partner_delivery_site_id,t.quantity,t.status,e.promised_delivery_date,COALESCE((SELECT c.new_date FROM supplier_po_delivery_tranche_change_events c WHERE c.tranche_id=t.id ORDER BY c.created_at DESC LIMIT 1),e.promised_delivery_date) FROM supplier_po_delivery_tranches t JOIN supplier_po_line_confirmation_events e ON e.id=t.supplier_po_line_confirmation_event_id WHERE t.id=p_tranche AND public.delivery_scope_allowed(p_actor,t.supplier_purchase_order_line_id); $$;
CREATE OR REPLACE FUNCTION public.prevent_delivery_tranche_change_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'DELIVERY_HISTORY_IMMUTABLE'; END $$;
CREATE TRIGGER delivery_tranche_change_immutable BEFORE UPDATE OR DELETE ON supplier_po_delivery_tranche_change_events FOR EACH ROW EXECUTE FUNCTION public.prevent_delivery_tranche_change_mutation();
REVOKE ALL ON FUNCTION public.delivery_scope_allowed(uuid,uuid),public.internal_partner_delivery_site_create(uuid,uuid,uuid,text,jsonb,jsonb,text),public.internal_supplier_po_delivery_tranche_create(uuid,uuid,uuid,uuid,numeric,text),public.internal_supplier_po_delivery_tranche_date_change(uuid,uuid,date,date,text,text),public.internal_supplier_po_delivery_tranche_get(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.internal_partner_delivery_site_create(uuid,uuid,uuid,text,jsonb,jsonb,text),public.internal_supplier_po_delivery_tranche_create(uuid,uuid,uuid,uuid,numeric,text),public.internal_supplier_po_delivery_tranche_date_change(uuid,uuid,date,date,text,text),public.internal_supplier_po_delivery_tranche_get(uuid,uuid) TO sco_internal_executor;
